#include <iostream>
#include <string>
#include <cctype>

static bool is_digit(char c) { return c >= '0' && c <= '9'; }
static bool is_alpha(char c) { return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_'; }
static bool is_alnum(char c) { return is_alpha(c) || is_digit(c); }

int main() {
    std::ios::sync_with_stdio(false);
    std::string line;
    if (!std::getline(std::cin, line)) return 0;

    std::size_t i = 0;
    while (i < line.size()) {
        char c = line[i];
        if (c == ' ' || c == '\t') { ++i; continue; }

        if (is_digit(c)) {
            std::size_t j = i;
            while (j < line.size() && is_digit(line[j])) ++j;
            std::cout << "NUM " << line.substr(i, j - i) << "\n";
            i = j;
        } else if (is_alpha(c)) {
            std::size_t j = i;
            while (j < line.size() && is_alnum(line[j])) ++j;
            std::cout << "IDENT " << line.substr(i, j - i) << "\n";
            i = j;
        } else if (c == '(') {
            std::cout << "LPAREN (\n";
            ++i;
        } else if (c == ')') {
            std::cout << "RPAREN )\n";
            ++i;
        } else {
            std::cout << "OP " << c << "\n";
            ++i;
        }
    }
    return 0;
}

