const line = readLines()[0] || '';

const isDigit = c => c >= '0' && c <= '9';
const isAlpha = c => (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c === '_';
const isAlnum = c => isAlpha(c) || isDigit(c);

let i = 0;
while (i < line.length) {
  const c = line[i];
  if (c === ' ' || c === '\t') { i += 1; continue; }

  if (isDigit(c)) {
    let j = i;
    while (j < line.length && isDigit(line[j])) j += 1;
    print('NUM ' + line.slice(i, j));
    i = j;
  } else if (isAlpha(c)) {
    let j = i;
    while (j < line.length && isAlnum(line[j])) j += 1;
    print('IDENT ' + line.slice(i, j));
    i = j;
  } else if (c === '(') {
    print('LPAREN (');
    i += 1;
  } else if (c === ')') {
    print('RPAREN )');
    i += 1;
  } else {
    print('OP ' + c);
    i += 1;
  }
}
